export const notInOrganizationView = <Message>(h: HtmlBuilder<Message>): Html =>
  screenView(
    message("notInOrganization.title"),
    [h.p([h.Class("mt-2 text-gray-600")], [message("notInOrganization.intro")]), signOutView(h)],
