        [h.Class("mt-4 flex flex-col gap-2")],
        organizations.map((org) =>
          h.li(
            [],
            [
              appButton(
                {
                  text: org.name,
                  isDisabled: busy,
                  onClick: onChoose(org.id),
                  className: `w-full text-left ${buttonClass}`,
                },
                h,
              ),
            ],
          ),
        ),
      ),
      signOutView(h),
    ],
    h,
