  // Open round check: response count only
  if (result.status === "open") {
    children.push(
      h.div(
        [h.Class("rounded-panel bg-primary-soft p-6")],
        [
          h.p([h.Class("font-semibold")], [message("results.openNotice")]),
          h.p(
            [h.Class("mt-1 text-sm text-muted")],
